-- pg_dumpall --roles-only (passwords replaced) + pg_dump --schema-only excerpts
CREATE ROLE postgres;
ALTER ROLE postgres WITH SUPERUSER INHERIT CREATEROLE CREATEDB LOGIN REPLICATION BYPASSRLS;
CREATE ROLE app;
ALTER ROLE app WITH SUPERUSER INHERIT NOCREATEROLE NOCREATEDB LOGIN NOREPLICATION NOBYPASSRLS PASSWORD 'md500000000000000000000000000000000';
CREATE ROLE etl;
ALTER ROLE etl WITH NOSUPERUSER INHERIT CREATEROLE NOCREATEDB LOGIN NOREPLICATION BYPASSRLS;
GRANT pg_read_server_files TO etl;

ALTER TABLE public.orders OWNER TO app;
ALTER TABLE public.invoices OWNER TO app;
ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.invoices USING (tenant_id = current_setting('app.tenant_id')::bigint);
GRANT CREATE ON SCHEMA public TO PUBLIC;
GRANT ALL ON TABLE public.orders TO etl;
GRANT SELECT ON TABLE public.orders TO reporting WITH GRANT OPTION;
